import {addLocaleData} from 'react-intl';

import locales, {localeData, isRtl} from 'scratch-l10n';
import editorMessages from 'scratch-l10n/locales/editor-msgs';

addLocaleData(localeData);

const UPDATE_LOCALES = 'scratch-gui/locales/UPDATE_LOCALES';
const SELECT_LOCALE = 'scratch-gui/locales/SELECT_LOCALE';

/**
 * Language menu option for Japanese with furigana. Selecting it sets the locale to 'ja' and turns on `furigana`,
 * which renders the text in Furifont (see lib/furigana.js).
 */
const FURIGANA_OPTION = 'ja-x-furigana';

/**
 * The language menu options: every supported locale, plus Japanese with furigana right after Japanese.
 */
const languageOptions = Object.keys(locales).reduce((options, locale) => (
    options.concat(locale === 'ja' ? [locale, FURIGANA_OPTION] : [locale])
), []);

/**
 * @param {string} option A language menu option.
 * @returns {string} the option's name.
 */
const getLanguageOptionName = option => (
    option === FURIGANA_OPTION ? '日本語（ふりがな付き）' : locales[option].name
);

/**
 * @param {object} state The locales state.
 * @returns {string} the language menu option of the state.
 */
const getLanguageOption = state => (state.furigana ? FURIGANA_OPTION : state.locale);

/**
 * @param {string} option A language menu option.
 * @returns {string} the locale of the option.
 */
const getLocaleOfOption = option => (option === FURIGANA_OPTION ? 'ja' : option);

const initialState = {
    furigana: false,
    isRtl: false,
    locale: 'en',
    messagesByLocale: editorMessages,
    messages: editorMessages.en
};

const reducer = function (state, action) {
    if (typeof state === 'undefined') state = initialState;
    switch (action.type) {
    case SELECT_LOCALE: {
        const locale = getLocaleOfOption(action.locale);
        return Object.assign({}, state, {
            furigana: action.locale === FURIGANA_OPTION,
            isRtl: isRtl(locale),
            locale: locale,
            messagesByLocale: state.messagesByLocale,
            messages: state.messagesByLocale[locale]
        });
    }
    case UPDATE_LOCALES:
        return Object.assign({}, state, {
            isRtl: state.isRtl,
            locale: state.locale,
            messagesByLocale: action.messagesByLocale,
            messages: action.messagesByLocale[state.locale]
        });
    default:
        return state;
    }
};

const selectLocale = function (locale) {
    return {
        type: SELECT_LOCALE,
        locale: locale
    };
};

const setLocales = function (localesMessages) {
    return {
        type: UPDATE_LOCALES,
        messagesByLocale: localesMessages
    };
};
const initLocale = function (currentState, option) {
    const locale = getLocaleOfOption(option);
    if (Object.prototype.hasOwnProperty.call(currentState.messagesByLocale, locale)) {
        return Object.assign(
            {},
            currentState,
            {
                furigana: option === FURIGANA_OPTION,
                isRtl: isRtl(locale),
                locale: locale,
                messagesByLocale: currentState.messagesByLocale,
                messages: currentState.messagesByLocale[locale]
            }
        );
    }
    // don't change locale if it's not in the current messages
    return currentState;
};
export {
    reducer as default,
    FURIGANA_OPTION,
    getLanguageOption,
    getLanguageOptionName,
    getLocaleOfOption,
    languageOptions,
    initialState as localesInitialState,
    initLocale,
    selectLocale,
    setLocales
};
